using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var binlogPath = args[0];
        var build = BinaryLog.ReadBuild(binlogPath);

        Console.WriteLine("=== BUILD RESULT: " + (build.Succeeded ? "SUCCESS" : "FAILED") + " ===\n");

        // Collect all errors
        var errors = new List<(string project, string code, string message, string file, int line)>();
        var warnings = new List<(string project, string code, string message, string file, int line)>();

        build.VisitAllChildren<Error>(error => {
            var project = GetParentProject(error);
            errors.Add((project, error.Code ?? "", error.Message ?? error.ToString(), error.File ?? "", error.LineNumber));
        });

        build.VisitAllChildren<Warning>(warning => {
            var project = GetParentProject(warning);
            warnings.Add((project, warning.Code ?? "", warning.Message ?? warning.ToString(), warning.File ?? "", warning.LineNumber));
        });

        // Group errors by project
        Console.WriteLine("=== ERRORS (" + errors.Count + " total) ===\n");
        foreach (var group in errors.GroupBy(e => e.project).OrderBy(g => g.Key))
        {
            Console.WriteLine($"--- Project: {group.Key} ({group.Count()} errors) ---");
            foreach (var e in group)
            {
                Console.WriteLine($"  [{e.code}] {e.file}({e.line}): {e.message}");
            }
            Console.WriteLine();
        }

        // Show relevant warnings
        if (warnings.Any(w => w.code.StartsWith("NU") || w.code.StartsWith("MSB")))
        {
            Console.WriteLine("=== NOTABLE WARNINGS ===\n");
            foreach (var w in warnings.Where(w => w.code.StartsWith("NU") || w.code.StartsWith("MSB")))
            {
                Console.WriteLine($"  [{w.code}] {w.project}: {w.message}");
            }
            Console.WriteLine();
        }

        // Show project dependency info
        Console.WriteLine("=== PROJECT BUILD ORDER & RESULTS ===\n");
        build.VisitAllChildren<Project>(project => {
            var hasErrors = false;
            project.VisitAllChildren<Error>(_ => hasErrors = true);
            if (hasErrors || !project.Succeeded)
            {
                Console.WriteLine($"  FAILED: {project.Name} (Target: {project.TargetFramework})");
            }
        });
    }

    static string GetParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p)
                return Path.GetFileName(p.ProjectFile ?? p.Name ?? "Unknown");
            current = current.Parent;
        }
        return "Unknown";
    }
}
EOF

