using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program2
{
    static void Main(string[] args)
    {
        var binlogPath = args[0];
        var build = BinaryLog.ReadBuild(binlogPath);

        // Check for dependency errors (MSB3202, MSB4236, etc.)
        Console.WriteLine("=== ALL PROJECTS IN BUILD ===\n");
        build.VisitAllChildren<Project>(project => {
            var pf = Path.GetFileName(project.ProjectFile ?? project.Name);
            var tfm = project.TargetFramework ?? "";
            bool hasErrors = false;
            project.VisitAllChildren<Error>(_ => hasErrors = true);
            Console.WriteLine($"  {(hasErrors ? "FAIL" : "OK  ")}: {pf} [{tfm}]");
        });

