using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        // Get detailed item info with metadata
        Console.WriteLine("=== PACKAGE REFERENCES (detailed) ===\n");
        build.VisitAllChildren<AddItem>(addItem => {
            if (addItem.Name == "PackageReference")
            {
                var project = GetParentProject(addItem);
                foreach (var child in addItem.Children)
                {
                    if (child is Item item)
                    {
                        Console.Write($"  {project} -> {item.Text}");
                        foreach (var meta in item.Children.OfType<Metadata>())
                            Console.Write($" [{meta.Name}={meta.Value}]");
                        Console.WriteLine();
                    }
                }
            }
        });

        Console.WriteLine("\n=== PROJECT REFERENCES (detailed) ===\n");
        build.VisitAllChildren<AddItem>(addItem => {
            if (addItem.Name == "ProjectReference")
            {
                var project = GetParentProject(addItem);
                foreach (var child in addItem.Children)
                {
                    if (child is Item item)
                        Console.WriteLine($"  {project} -> {item.Text}");
                }
            }
        });

        // Dump all errors with full context
        Console.WriteLine("\n=== ALL ERRORS ===\n");
        build.VisitAllChildren<Error>(error => {
            var project = GetParentProject(error);
            Console.WriteLine($"  Project: {project}");
            Console.WriteLine($"  Code: {error.Code}");
            Console.WriteLine($"  File: {error.File}:{error.LineNumber}");
            Console.WriteLine($"  Text: {error.Text}");
            Console.WriteLine();
        });

        // Show source files from the build
        Console.WriteLine("=== COMPILE ITEMS ===\n");
        build.VisitAllChildren<AddItem>(addItem => {
            if (addItem.Name == "Compile")
            {
                var project = GetParentProject(addItem);
                foreach (var child in addItem.Children)
                {
                    if (child is Item item)
                        Console.WriteLine($"  {project}: {item.Text}");
                }
            }
        });
    }

    static string GetParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p)
                return Path.GetFileName(p.ProjectFile ?? p.Name ?? "Unknown");
            current = current.Parent;
        }
        return "Unknown";
    }
}
