using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args[0]);

        // Extract embedded source files from the binlog archive
        Console.WriteLine("=== EMBEDDED FILES ===\n");
        var allNodes = new List<BaseNode>();
        CollectAll(build, allNodes);

        foreach (var node in allNodes)
        {
            var typeName = node.GetType().Name;
            if (typeName.Contains("Archive") || typeName.Contains("SourceFile") || typeName.Contains("Embed"))
                Console.WriteLine($"  [{typeName}] {node.ToString()?.Substring(0, Math.Min(node.ToString()?.Length ?? 0, 200))}");
        }

        // Look for project evaluation to find PackageReference items
        Console.WriteLine("\n=== EVALUATION ITEMS (PackageReference) ===\n");
        build.VisitAllChildren<NamedNode>(nn => {
            if (nn.Name == "PackageReference" && nn.HasChildren)
            {
                var project = GetParentProject(nn);
                Console.Write($"  {project} -> PackageReference:");
                foreach (var child in nn.Children)
                    Console.Write($" {child}");
                Console.WriteLine();
            }
        });

        // Dump tree structure around Services.csproj
        Console.WriteLine("\n=== SERVICES.CSPROJ EVAL TREE ===\n");
        build.VisitAllChildren<Project>(p => {
            if (Path.GetFileName(p.ProjectFile ?? "") == "Services.csproj")
            {
                // Look for Folder nodes that contain items
                foreach (var child in p.Children)
                {
                    if (child is BaseNode bn)
                    {
                        var s = bn.ToString() ?? "";
                        if (s.Contains("Package", StringComparison.OrdinalIgnoreCase) || 
                            s.Contains("Item", StringComparison.OrdinalIgnoreCase) ||
                            s.Contains("Evaluation", StringComparison.OrdinalIgnoreCase))
                        {
                            Console.WriteLine($"  [{bn.GetType().Name}] {s.Substring(0, Math.Min(s.Length, 200))}");
                            if (bn.HasChildren)
                            {
                                foreach (var gc in bn.Children)
                                {
                                    if (gc is BaseNode gcbn)
                                    {
                                        var gs = gcbn.ToString() ?? "";
                                        if (gs.Contains("Package", StringComparison.OrdinalIgnoreCase))
                                            Console.WriteLine($"    [{gcbn.GetType().Name}] {gs.Substring(0, Math.Min(gs.Length, 200))}");
                                    }
                                }
                            }
                        }
                    }
                }
            }
        });
    }

    static void CollectAll(BaseNode node, List<BaseNode> result)
    {
        result.Add(node);
        if (node.HasChildren)
            foreach (var child in node.Children)
                if (child is BaseNode bn)
                    CollectAll(bn, result);
    }

    static string GetParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p)
                return Path.GetFileName(p.ProjectFile ?? p.Name ?? "Unknown");
            current = current.Parent;
        }
        return "Unknown";
    }
}
