        Console.WriteLine("\n=== TRYING TO READ EMBEDDED PROJECT FILES ===\n");
        var archives = new List<ArchiveFile>();
        build.VisitAllChildren<ArchiveFile>(af => archives.Add(af));
        Console.WriteLine($"Found {archives.Count} archive files");
        foreach (var af in archives)
        {
            Console.WriteLine($"\n--- {af.Name} ---");
            var text = af.Text;
            if (text != null)
                Console.WriteLine(text.Length > 3000 ? text.Substring(0, 3000) + "..." : text);
            else
                Console.WriteLine("(no text)");
        }
    }

